% Parameterized plot dispatcher for a month.
project='F:\AER_SHARED_PIPELINE'; run_id=getenv('FULL_MONTH_RUN_ID'); if isempty(run_id),run_id=fullfile('produce','run_200701_month_004');end; run_id=strrep(run_id,'/','\'); if ~startsWith(run_id,'produce\'), if isempty(regexp(run_id,'[\\/]','once')),run_id=fullfile('produce',run_id);else,error('FullMonth:RunCategory','RunId must be produce\run_<id> (or a bare run_<id>).');end,end; y=str2double(getenv('FULL_MONTH_YEAR'));m=str2double(getenv('FULL_MONTH_MONTH'));if isnan(y),y=2007;end;if isnan(m),m=1;end;ym=sprintf('%04d%02d',y,m);run_root=fullfile(project,'runs',run_id);logdir=fullfile(run_root,'logs','full_pipeline');if ~isfolder(logdir),mkdir(logdir);end;fid=fopen(fullfile(logdir,'plots_pipeline.log'),'a');sf=fopen(fullfile(logdir,'plot_status.csv'),'w');fprintf(sf,'Component,Output,Status,Message\n');fails=0;
try,ch5=fullfile(project,'products','chapter5','chapter5_map_stats','ch5map__era5-real__grid5deg__n50-v1','monthly',sprintf('%04d',y),sprintf('%02d',m),['CHAPTER5_MAP_STATS_' ym '.mat']);out=fullfile(run_root,'plots','chapter5');if ~isfile(ch5),error('Missing Chapter5 map product');end;if ~isfolder(out),mkdir(out);end;setenv('CHAPTER5_MAP_STATS_INPUT',ch5);setenv('CHAPTER5_OUTPUT_DIR',out);setenv('CHAPTER5_PLOT_LABEL',sprintf('%04d-%02d',y,m));run(fullfile(project,'plots','chapter5','plot_chapter5_map_stats.m'));pass(fid,sf,'Chapter5',fullfile(out,'Figure_5_1.png'));catch ME,fails=fails+1;fail(fid,sf,'Chapter5','Figure_5_1.png',ME);end
try,ccn=fullfile(project,'products','ccn','ccn_grid_monthly','ccn-monthly__ap-final-v1__era5-real__grid5deg__ccn-v1',sprintf('%04d',y),sprintf('%02d',m),['CCN_GRID_Monthly_' ym '.mat']);out=fullfile(run_root,'plots','ccn');if ~isfile(ccn),error('Missing CCN monthly product');end;if ~isfolder(out),mkdir(out);end;addpath(fullfile(project,'code','consumers','ccn'),'-begin');plot_ccn_monthly_pretty(ccn,out,[ym '_month']);pass(fid,sf,'CCN',fullfile(out,['CCN_' ym '_month_pretty.png']));catch ME,fails=fails+1;fail(fid,sf,'CCN','monthly_pretty',ME);end
col=fullfile(run_root,'intermediate','chapter4',['AERONET_CALIPSO_Column_Integrated_DB_' ym '.mat']);figdir=fullfile(run_root,'plots','chapter4');if ~isfolder(figdir),mkdir(figdir);end;addpath(fullfile(project,'code','consumers','chapter4'),'-begin');addpath(fullfile(project,'code','functions'),'-begin');setenv('CHAPTER4_CODE_ROOT',fullfile(project,'code'));setenv('CHAPTER4_PROJECT_DIR',run_root);setenv('CHAPTER4_COLUMN_INPUT_FILE',col);setenv('CHAPTER4_FIG_DIR',figdir);set(0,'DefaultFigureVisible','off');jobs={{'Figure4_1','1','figure_4_1and4_2.m','Figure_4_1.png'},{'Figure4_2','2','figure_4_1and4_2.m','Figure_4_2.png'},{'Figure4_3','0','figure_4_3.m','Figure_4_3_Panel_1.png'},{'Figure4_4','0','figure_4_4.m','Figure_4_4.png'},{'Figure4_5','0','figure_4_5.m','Figure_4_5.png'}};if ~isfile(col),fails=fails+1;fail(fid,sf,'Chapter4','ALL',MException('Missing Column DB'));else,for k=1:numel(jobs),j=jobs{k};try,if ~strcmp(j{2},'0'),setenv('CHAPTER4_PLOT_PARAMETER',j{2});end;run(fullfile(project,'code','consumers','chapter4','画图代码',j{3}));pass(fid,sf,j{1},fullfile(figdir,j{4}));catch ME,fails=fails+1;fail(fid,sf,j{1},j{4},ME);end,end,end
fprintf(fid,'END fails=%d\n',fails);fclose(fid);fclose(sf);if fails>0,error('Plot jobs failed: %d',fails);end
function pass(fid,sf,c,o),fprintf(fid,'PASS %s %s\n',c,o);fprintf(sf,'%s,%s,PASS,\n',c,o);end
function fail(fid,sf,c,o,ME),m=strrep(ME.message,',',';');fprintf(fid,'FAIL %s %s\n%s\n',c,o,getReport(ME,'extended','hyperlinks','off'));fprintf(sf,'%s,%s,FAIL,%s\n',c,o,m);end
